param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))

$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$c,[string]$m){if(-not$c){throw $m}}
function Pump([int]$ms){$f=New-Object Windows.Threading.DispatcherFrame;$t=New-Object Windows.Threading.DispatcherTimer;$t.Interval=[TimeSpan]::FromMilliseconds($ms);$t.Add_Tick({$t.Stop();$f.Continue=$false});$t.Start();[Windows.Threading.Dispatcher]::PushFrame($f)}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$pointType=$assembly.GetType('HalconWinFormsDemo.Models.VmPoint2D',$true);$arrayType=$assembly.GetType('HalconWinFormsDemo.Models.VmPoint2DArray',$true);$lineType=$assembly.GetType('HalconWinFormsDemo.Models.VmLine2D',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s72-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 180
function F([string]$n){$v=$main.GetField($n,$all).GetValue($window);Write-Output -NoEnumerate $v}
function M([string]$n,[object[]]$p=@()){try{$main.GetMethod($n,$private).Invoke($window,$p)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw($n+': '+$e.Message)}}
function K([string]$n){[Enum]::Parse($kindType,$n)}
function Tool([string]$k,[string]$n){M 'CreateFlowTool' ([object[]]@((K $k),$n,$true,$null))}
function Run($t){M 'ExecuteFlowTool' ([object[]]@($t,'S72 smoke'))}
function Out($t,[string]$p){$a=[object[]]@($p,$null);if(-not$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)){throw"Missing output $p"};$a[1]}
function Has($t,[string]$p){$a=[object[]]@($p,$null);[bool]$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)}
function Points([double[]]$r,[double[]]$c,[string]$ctx){$arrayType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r,$c,$ctx))}
function Line([double]$r1,[double]$c1,[double]$r2,[double]$c2,[string]$ctx){$lineType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r1,$c1,$r2,$c2,$ctx))}
function SelectTools([object[]]$tools){(F 'FlowToolList').SelectedItems.Clear();foreach($tool in $tools){(F 'FlowToolList').SelectedItems.Add($tool)}}
try{
  Assert ((F 'toolCatalog').Count-eq73 -and (F 'toolCatalog').Count-eq[Enum]::GetValues($kindType).Count) 'S72 compatibility catalog mismatch after S80.'
  Assert ((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S72 added a permanent top command.'

  # A: compact vertical long flow, external flexible lanes, focus-only labels and top-to-bottom navigation.
  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$a=Tool 'ImageSource' '01 Input';$b=Tool 'ImageFilter' '02 Filter';$c=Tool 'ImageEnhancement' '03 Enhance';$d=Tool 'ImageMirror' '04 Mirror';$e=Tool 'ImageRotate' '05 Rotate';$f=Tool 'ImageThreshold' '06 Segment';foreach($t in @($a,$b,$c,$d,$e,$f)){$flow.Add($t)}
  $b.SetInputBinding('Image',$a.ToolId,'Image');$c.SetInputBinding('Image',$b.ToolId,'Image');$d.SetInputBinding('Image',$c.ToolId,'Image');$e.SetInputBinding('Image',$d.ToolId,'Image');$f.SetInputBinding('Image',$e.ToolId,'Image')
  (F 'FlowToolList').SelectedItem=$null;M 'RefreshFlowGraphLayout'|Out-Null
  $ordered=@($flow|Sort-Object GraphY);Assert (($ordered|Select-Object -ExpandProperty GraphX|Select-Object -Unique).Count-eq1 -and $ordered[0].GraphY-lt$ordered[5].GraphY -and (@($ordered|Where-Object {$_.GraphHeight-gt74.1}).Count-eq0)) 'Default flow is not compact top-to-bottom.'
  $connections=F 'flowConnections';Assert ($connections.Count-eq5) ('Long-flow dependency count mismatch: '+$connections.Count);Assert (@($connections|Where-Object IsLabelVisible).Count-eq0) 'Unfocused legal connections still expose labels.';Assert (@($connections|Where-Object {$_.StrokeOpacity-gt0.55}).Count-eq0) 'Unfocused connections were not visually reduced.'
  Assert (@($connections|Where-Object {$_.LabelX-gt($ordered[0].GraphX+300)}).Count-gt0) 'Flexible lane does not clear compact node bounds.'
  (F 'FlowToolList').SelectedItem=$d;M 'RefreshFlowGraphLayout'|Out-Null;$focused=@((F 'flowConnections')|Where-Object IsFocusPath);Assert ($focused.Count-eq2 -and @($focused|Where-Object IsLabelVisible).Count-eq0 -and @($focused|Where-Object {$_.StrokeOpacity-lt0.7}).Count-eq0) 'Selected-step dependency focus is incomplete or too noisy.'
  M 'SelectAdjacentFlowToolS72' ([object[]]@(-1,'smoke'))|Out-Null;Assert ((F 'FlowToolList').SelectedItem.ToolId-eq$c.ToolId) 'Alt-up navigation core did not select previous module.';M 'SelectAdjacentFlowToolS72' ([object[]]@(1,'smoke'))|Out-Null;Assert ((F 'FlowToolList').SelectedItem.ToolId-eq$d.ToolId) 'Alt-down navigation core did not select next module.'
  $d.IsExecutionPointer=$true;$main.GetField('isFlowExecutionActive',$private).SetValue($window,$true);M 'PauseFlowExecutionFollowS72' ([object[]]@('smoke pause'))|Out-Null;Assert ([bool](F 'flowExecutionFollowPausedS72')) 'Manual navigation did not pause automatic execution follow.';M 'LocateExecutionPointerS72'|Out-Null;Pump 80;Assert ((-not[bool](F 'flowExecutionFollowPausedS72')) -and (F 'FlowToolList').SelectedItem.ToolId-eq$d.ToolId) 'Locate current execution did not resume follow and select pointer.';$main.GetField('isFlowExecutionActive',$private).SetValue($window,$false);$d.IsExecutionPointer=$false

  # B: Point2D[] -> HALCON fit_line_contour_xld -> Line2D/residual/XLD -> typed and numeric downstreams.
  M 'DisposeFlowTools'|Out-Null;$flow.Clear();$source=Tool 'CircularCaliperCircleFinder' 'Point Producer';$fit=Tool 'TypedPointSetLineFittingMeasurement' 'Typed Point Fit';$distance=Tool 'PointToLineDistanceMeasurement' 'Start To Fit';$lineRef=Tool 'XldLineFitting' 'Reference Line';$relation=Tool 'TypedLineLineRelationMeasurement' 'Fitted Line Relation';$judge=Tool 'NumericJudge' 'Residual Judge';foreach($t in @($source,$fit,$distance,$lineRef,$relation,$judge)){$flow.Add($t)}
  $fit.SetInputBinding('Points',$source.ToolId,'EdgePoints');$distance.SetInputBinding('Point',$fit.ToolId,'StartPoint');$distance.SetInputBinding('Line',$fit.ToolId,'MainLine');$relation.SetInputBinding('LineA',$fit.ToolId,'MainLine');$relation.SetInputBinding('LineB',$lineRef.ToolId,'MainLine');$judge.SetInputBinding('Value',$fit.ToolId,'MaxResidual');$judge.InputToolId=$fit.ToolId;$judge.InputPortName='MaxResidual';$judge.NumericOperator='LessOrEqual';$judge.NumericUpperLimit=0.001
  $ctx='S72.Image';$clean=Points ([double[]](1,3,5,7,9)) ([double[]](0,1,2,3,4)) $ctx;$source.SetOutputValue('EdgePoints',$clean);$source.ResultCode='OK';$fit.Parameters.PointSetMinimumCount=3;$fit.Parameters.XldLineFitAlgorithm='regression';$result=Run $fit
  $line=Out $fit 'MainLine';$residual=[double](Out $fit 'MaxResidual');$xld=Out $fit 'XLD';Write-Output ('S72_TYPED_POINT_FIT='+$result.ResultCode+'|'+$line.ToDisplayString()+'|MaxResidual='+$residual+'|XLD='+$xld.ObjectCount)
  Assert (($result.ResultCode-eq'OK') -and $line.CoordinateContextId-eq$ctx -and [Math]::Abs($line.DirectionAngleDegrees-63.4349488)-lt0.01 -and $residual-lt0.0001 -and $xld.ObjectCount-eq12) 'HALCON typed point-set line fit outputs are wrong.'
  $lineRef.SetOutputValue('MainLine',(Line 5 0 5 10 $ctx));$lineRef.ResultCode='OK';$relationResult=Run $relation;$distanceResult=Run $distance;$judgeResult=Run $judge;Assert (($relationResult.ResultCode-eq'OK') -and (-not[bool](Out $relation 'IsParallel')) -and (Has $relation 'IntersectionPoint') -and ($distanceResult.ResultCode-eq'OK') -and ([double](Out $distance 'Distance'))-lt0.0001 -and $judgeResult.ResultCode-eq'OK') 'MainLine to S71 relation/point-line or residual downstream chain failed.'
  $fit.Parameters.XldLineFitAlgorithm='tukey';$fit.Parameters.XldLineFitIterations=10;$robustRows=[double[]](@(0..49|ForEach-Object{2.0*$_+1.0})+@(50.0));$robustColumns=[double[]](@(0..49|ForEach-Object{[double]$_})+@(200.0));$robust=Points $robustRows $robustColumns $ctx;$source.SetOutputValue('EdgePoints',$robust);$source.ResultCode='OK';$robustResult=Run $fit;$robustLine=Out $fit 'MainLine';$robustResidual=[double](Out $fit 'MaxResidual');Write-Output ('S72_TUKEY_OUTLIER='+$robustResult.ResultCode+'|Angle='+$robustLine.DirectionAngleDegrees+'|MaxResidual='+$robustResidual);Assert (($robustResult.ResultCode-eq'OK') -and [Math]::Abs($robustLine.DirectionAngleDegrees-63.4349488)-lt1.0 -and $robustResidual-gt100) 'Tukey robust line fit did not preserve the inlier direction or expose the outlier residual.'
  (F 'FlowToolList').SelectedItem=$fit;M 'LoadDockConfigurationDraft' ([object[]]@($fit))|Out-Null;Assert ((F 'DockTypedPointSetLineFitPanel').Visibility.ToString()-eq'Visible' -and (F 'DockTypedPointSetLineFitAlgorithmComboBox').SelectedValue-eq'tukey') 'Typed point-set line parameters are not in the persistent right dock.'
  M 'RefreshPortDataMonitorS64' ([object[]]@($fit))|Out-Null;Assert (@((F 'portDataMonitorRows')|Where-Object {$_.DataType-eq'Point2D[]' -or $_.DataType-eq'Line2D'}).Count-ge2) 'I/O monitor did not expose typed point-set/line ports.'
  $old=Out $fit 'XLD';$source.SetOutputValue('EdgePoints',(Points ([double[]](2,4,6,8)) ([double[]](0,1,2,3)) $ctx));$source.ResultCode='OK';Run $fit|Out-Null;Assert $old.IsDisposed 'Rerun did not dispose old managed XLD.'
  $fit.Parameters.PointSetMinimumCount=4;$fit.Parameters.PointSetAbnormalPolicy='SkipInvalid';$mixed=Points ([double[]](2,4,6,8,10)) ([double[]](0,1,2,3,4)) $ctx;$mixed.Points[4].IsValid=$false;$source.SetOutputValue('EdgePoints',$mixed);$source.ResultCode='OK';$skip=Run $fit;Assert (($skip.ResultCode-eq'NG') -and ([double](Out $fit 'ValidCount'))-eq4 -and ([double](Out $fit 'RejectedCount'))-eq1 -and (Has $fit 'MainLine')) 'SkipInvalid semantics or diagnostic outputs failed.'
  $fit.Parameters.PointSetAbnormalPolicy='Reject';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Reject policy accepted an invalid point.'
  $fit.Parameters.PointSetAbnormalPolicy='SkipInvalid';$cross=Points ([double[]](1,3,5)) ([double[]](0,1,2)) $ctx;$cross.Points[1].CoordinateContextId='Other.Image';$source.SetOutputValue('EdgePoints',$cross);$source.ResultCode='OK';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Mixed coordinate contexts were accepted.'
  $source.SetOutputValue('EdgePoints',(Points ([double[]](1,1,1,1)) ([double[]](2,2,2,2)) $ctx));$source.ResultCode='OK';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Degenerate coincident point set was accepted.'
  $source.SetOutputValue('EdgePoints',(Points ([double[]](1,3,5,7)) ([double[]](0,1,2,3)) $ctx));$source.ResultCode='--';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Stale/unrun Point2D[] source was accepted.'
  $source.ResultCode='OK';$fit.Parameters.PointSetMinimumCount=3;$fit.Parameters.PointSetAbnormalPolicy='Reject';$fit.Parameters.XldLineFitAlgorithm='tukey';$recipe=M 'CaptureRecipe';$saved=$recipe.ToolFlow|Where-Object ToolId -eq $fit.ToolId|Select-Object -First 1;Assert (($saved.Parameters.PointSetMinimumCount-eq3) -and $saved.Parameters.XldLineFitAlgorithm-eq'tukey') 'Recipe lost typed point-set line parameters.'
  SelectTools @($source,$fit);$copied=[int](M 'CopySelectedFlowToolsToClipboard');$pasted=[int](M 'PasteFlowToolClipboard' ([object[]]@($flow.Count)));$copyBlock=@($flow|Select-Object -Last 2);$copyFit=$copyBlock|Where-Object {$_.Kind.ToString()-eq'TypedPointSetLineFittingMeasurement'}|Select-Object -First 1;Assert (($copied-eq2) -and ($pasted-eq2) -and $copyFit.GetInputBinding('Points').SourceToolId-eq$copyBlock[0].ToolId) 'Typed point-set line block copy did not remap Points source.'
  Write-Output 'S72 vertical long-flow focus/navigation/follow + HALCON typed Point2D[] line fitting/downstreams/dock/I-O/recipe/copy/lifecycle/failures passed'
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
